    /** A loop-registered family member (block_cap_nuka, casing_large_steel, ...) by its hbm registry id. */
    private static net.minecraft.world.item.Item item(String id) {
        return net.minecraft.core.registries.BuiltInRegistries.ITEM.getOptional(Ids.of("hbm", id))
                .orElseThrow(() -> new IllegalStateException("generated machine recipe names unregistered hbm:" + id));
    }

    /** Ad-hoc c:/minecraft tag ingredient (materials without an NTMMaterial helper shape). */
    private static AStack tag(String ns, String path, int count) {
        return new TagStack(TagKey.create(Registries.ITEM, Ids.of(ns, path)), count);
    }
